export type UsageSummary_Deserialize = {
	range: UsageRange_Deserialize,
	totals: UsageTotals_Deserialize,
	/**
	 *  Every day of the range, oldest first, with zero days filled in. For
	 *  an open range it starts at the first recorded day.
	 */
	days: DayUsage_Deserialize[],
	/**  Most tokens first. */
	agents: AgentUsage_Deserialize[],
	/**  Most tokens first. */
	models: ModelUsage_Deserialize[],
	/**  The model with the most tokens (turns when no tokens were reported). */
	topModel?: string | null,
	prices: PriceTableInfo,
	/**  Sessions with any usage counters at all, in or out of the range. */
	trackedSessions: number,
};

export type UsageSummary_Serialize = {
	range: UsageRange_Serialize,
	totals: UsageTotals_Serialize,
	/**
	 *  Every day of the range, oldest first, with zero days filled in. For
	 *  an open range it starts at the first recorded day.
	 */
	days: DayUsage_Serialize[],
	/**  Most tokens first. */
	agents: AgentUsage_Serialize[],
	/**  Most tokens first. */
	models: ModelUsage_Serialize[],
	/**  The model with the most tokens (turns when no tokens were reported). */
	topModel: string | null,
	prices: PriceTableInfo,
	/**  Sessions with any usage counters at all, in or out of the range. */
	trackedSessions: number,
};

/**  Sums for a group of buckets. */
export type UsageTotals = UsageTotals_Serialize | UsageTotals_Deserialize;

/**  Sums for a group of buckets. */
export type UsageTotals_Deserialize = {
	tokens: TokenCounts_Deserialize,
	turns: number,
	/**  Turns whose agent reported token counts. */
	turnsWithTokens: number,
	sessions: number,
	cost: UsageCost,
};

/**  Sums for a group of buckets. */
export type UsageTotals_Serialize = {
	tokens: TokenCounts_Serialize,
	turns: number,
	/**  Turns whose agent reported token counts. */
	turnsWithTokens: number,
	sessions: number,
	cost: UsageCost,
};

/**  A non-text block in a replayed user turn, kept as a marker. */
export type UserAttachment = UserAttachment_Serialize | UserAttachment_Deserialize;

/**  A non-text block in a replayed user turn, kept as a marker. */
export type UserAttachment_Deserialize = {
	/**  `resourceLink`, `image` or `resource`. */
	kind: string,
	uri?: string | null,
	name?: string | null,
	mimeType?: string | null,
};

/**  A non-text block in a replayed user turn, kept as a marker. */
export type UserAttachment_Serialize = {
	/**  `resourceLink`, `image` or `resource`. */
	kind: string,
	uri: string | null,
	name: string | null,
	mimeType: string | null,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

export type WatchRecoveryPhase =
/**  An automatic restart is about to happen. Shown quietly in the status popover. */
"refreshing" |
/**  The automatic restart finished. */
"refreshed" |
/**  Automatic restarts are used up for now. The user may restart it. */
"exhausted";

export type WorkProgressKindDto = "begin" | "report" | "end";

export type Workspace = {
	root: string,
	name: string,
};

/**
 *  A rename result. Nothing is applied here: the UI applies it through the buffer edit
 *  path.
 */
export type WorkspaceEditDto = {
	files: FileEditsDto[],
	/**
	 *  File create, rename and delete operations the server sent anyway. Span declares
	 *  no resource operation support and never performs them.
	 */
	skippedOperations: number,
};

export type WorkspaceSymbolDto = WorkspaceSymbolDto_Serialize | WorkspaceSymbolDto_Deserialize;

export type WorkspaceSymbolDto_Deserialize = {
	name: string,
	kind: SymbolKindDto,
	containerName?: string | null,
	location: LocationDto,
};

export type WorkspaceSymbolDto_Serialize = {
	name: string,
	kind: SymbolKindDto,
	containerName: string | null,
	location: LocationDto,
};

/**  A decision was stored for `root` (the open workspace folder). */
export type WorkspaceTrustChanged = {
	root: string,
	decision: WorkspaceTrustDecision,
};

/**  The decision for the current workspace, including "not decided yet". */
export type WorkspaceTrustDecision = "trusted" | "restricted" | "undecided";

export type WorkspaceTrustStateDto = WorkspaceTrustStateDto_Serialize | WorkspaceTrustStateDto_Deserialize;

export type WorkspaceTrustStateDto_Deserialize = {
	decision: WorkspaceTrustDecision,
	/**  The decision comes from a parent folder (or the global override), not from this folder. */
	inherited: boolean,
	/**  The folder that decided. Absent when undecided or when the global override applies. */
	source?: string | null,
	/**  Undecided and the folder holds files that make language servers run project code. */
	needsPrompt: boolean,
	reason?: string | null,
	buildFiles: string[],
};

export type WorkspaceTrustStateDto_Serialize = {
	decision: WorkspaceTrustDecision,
	/**  The decision comes from a parent folder (or the global override), not from this folder. */
	inherited: boolean,
	/**  The folder that decided. Absent when undecided or when the global override applies. */
	source: string | null,
	/**  Undecided and the folder holds files that make language servers run project code. */
	needsPrompt: boolean,
	reason: string | null,
	buildFiles: string[],
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

